export const TARGET_APPLICATIONS_MAP: Record<string, TargetCompanyApplication> = TARGET_APPLICATIONS.reduce((acc, app) => {
  acc[app.id] = app;
  return acc;
}, {} as Record<string, TargetCompanyApplication>);

/** Helper to get application by ID or company name */
export function getTargetApplication(idOrCompany: string): TargetCompanyApplication | undefined {
  if (TARGET_APPLICATIONS_MAP[idOrCompany]) {
    return TARGET_APPLICATIONS_MAP[idOrCompany];
  }
  const normalized = idOrCompany.trim().toLowerCase();
  return TARGET_APPLICATIONS.find(
    app => app.id.toLowerCase() === normalized || app.company.toLowerCase() === normalized
  );
}
